const r = $json;
const raw = r.body ?? r.data ?? r;
const bodyText = typeof raw === 'string' ? raw : JSON.stringify(raw);
const status = Number(r.statusCode ?? r.status ?? r.response?.statusCode ?? 0);
const challengePattern = /آیا\s*شما\s*یک\s*ربات\s*هستید|are\s+you\s+a\s+robot|captcha|challenge-platform|cf-chl-|verify\s+you\s+are\s+human/i;
const isChallenge = challengePattern.test(bodyText);
const blockedStatus = [403, 429, 490].includes(status);
let parsed = raw;
if (typeof raw === 'string' && !isChallenge) {
  try { parsed = JSON.parse(raw); } catch (e) { parsed = { raw_response: raw }; }
}
const blocked = isChallenge || blockedStatus;
const reason = isChallenge ? 'anti_bot_challenge' : (blockedStatus ? 'http_' + status : null);
const payload = parsed && typeof parsed === 'object' && !Array.isArray(parsed) ? parsed : { response: parsed };
return [{ json: { ...payload, _torob_guard: { blocked, status_code: status || null, reason, response_preview: blocked ? bodyText.slice(0, 500) : undefined } } }];

